/**
 * Model Tenant
 * 租户（产品语义"团队"；§3.2 域 1）
 */
export type Tenant = $Result.DefaultSelection<Prisma.$TenantPayload>
/**
 * Model User
 * 用户（登录名；系统级实体，无 tenant_id。SSO 用户 password_hash 可空）
 */
export type User = $Result.DefaultSelection<Prisma.$UserPayload>
/**
 * Model MemberProfile
 * 成员画像 ★D2（Phase 1 迁移必须就位；完成率/准时率不落表，由 tasks 聚合计算）
 */
export type MemberProfile = $Result.DefaultSelection<Prisma.$MemberProfilePayload>
/**
 * Model Role
 * 角色模板（tenant_id NULL = 系统级模板；租户克隆/覆盖/自定义，⚠️ 自定义角色数上限待确认）
 */
export type Role = $Result.DefaultSelection<Prisma.$RolePayload>
/**
 * Model UserRole
 * 用户-角色分配（scope_resource_id 空 = 租户级；非空 = 项目级/任务级资源 id）
 */
export type UserRole = $Result.DefaultSelection<Prisma.$UserRolePayload>
/**
 * Model Project
 * 项目（大计划；owner_id = 项目负责人，项目级角色依据，非独立角色实体）
 */
export type Project = $Result.DefaultSelection<Prisma.$ProjectPayload>
/**
 * Model Task
 * 任务 ★核心表（显式状态机见 §3.3：todo/in_progress/blocked/done/cancelled + PendingReview 扩展态；常量定义见 common/constants/task-status.ts）
 */
export type Task = $Result.DefaultSelection<Prisma.$TaskPayload>
/**
 * Model TimeEntry
 * 计时记录（stop 计时写 time_entries，累计 actual_hours）
 */
export type TimeEntry = $Result.DefaultSelection<Prisma.$TimeEntryPayload>
/**
 * Model TaskDependency
 * 任务依赖 ★核心表（Phase 1 建表就位、Phase 2 启用；type: FS/SS/FF/SF 四类依赖）
 */
export type TaskDependency = $Result.DefaultSelection<Prisma.$TaskDependencyPayload>
/**
 * Model PersonalTask
 * 个人任务 ★（独立实体，★D3 断点表：Phase 1 迁移必须就位；状态机同团队任务；与团队任务提升/关联 ⚠️ 待确认，预留 linked_task_id）
 */
export type PersonalTask = $Result.DefaultSelection<Prisma.$PersonalTaskPayload>
/**
 * Model TaskComment
 * 任务评论/回复串（@提及解析 → 通知；关键决策标记 Phase 2 AI 增强）
 */
export type TaskComment = $Result.DefaultSelection<Prisma.$TaskCommentPayload>
/**
 * Model AiProposal
 * AI 提议 ★核心表（Phase 1 迁移必须就位；独立状态机：pending → approved → applied/rejected/expired，§3.3 补充规则；approved 未 applied 不产生业务副作用）
 */
export type AiProposal = $Result.DefaultSelection<Prisma.$AiProposalPayload>
/**
 * Model Notification
 * 通知（站内为主；其他通道看 NotificationDelivery 投递记录）
 */
export type Notification = $Result.DefaultSelection<Prisma.$NotificationPayload>
/**
 * Model NotificationDelivery
 * 通知投递记录（多通道外发状态/重试；notifications.service 外发流程使用）
 */
export type NotificationDelivery = $Result.DefaultSelection<Prisma.$NotificationDeliveryPayload>
/**
 * Model NotificationPreference
 * 通知偏好（事件类型 → 三通道开关 + 免打扰时段）
 */
export type NotificationPreference = $Result.DefaultSelection<Prisma.$NotificationPreferencePayload>
/**
 * Model Reminder
 * 提醒（双保险：Redis zset 主队列 + pg_cron/应用定时器 DB 兜底扫描；trigger_at 为 zset score 来源，决策 4）
 */
export type Reminder = $Result.DefaultSelection<Prisma.$ReminderPayload>
/**
 * Model AuditLog
 * 审计日志（append-only：只插入不更新不删除；@Audited 装饰器 + AuditService 写入；actor_type 区分 user/system/ai，决策 8）
 */
export type AuditLog = $Result.DefaultSelection<Prisma.$AuditLogPayload>
/**
 * Model Attachment
 * 附件（对象存储，S3 兼容；object_key 带 tenant_id 前缀隔离；大小 <=20MB、类型白名单，§3.5.5）
 */
export type Attachment = $Result.DefaultSelection<Prisma.$AttachmentPayload>
/**
 * Model ProjectTemplate
 * 
 */
export type ProjectTemplate = $Result.DefaultSelection<Prisma.$ProjectTemplatePayload>
/**
 * Model AutomationRule
 * 
 */
export type AutomationRule = $Result.DefaultSelection<Prisma.$AutomationRulePayload>
/**
 * Model ApiKey
 * 
 */
export type ApiKey = $Result.DefaultSelection<Prisma.$ApiKeyPayload>
/**
 * Model Webhook
 * 
 */
export type Webhook = $Result.DefaultSelection<Prisma.$WebhookPayload>
/**
 * Model CalendarAccount
 * 
 */
export type CalendarAccount = $Result.DefaultSelection<Prisma.$CalendarAccountPayload>
/**
 * Model CalendarEventMapping
 * 
 */
export type CalendarEventMapping = $Result.DefaultSelection<Prisma.$CalendarEventMappingPayload>

